import{_ as n,l as c,o as a,c as s,v as r,p as i,x as o,d,i as l,S as E}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"E2B / Docker agent 沙箱","description":"","frontmatter":{"title":"E2B / Docker agent 沙箱","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/agent-sandbox-e2b.md","filePath":"llm/agent-sandbox-e2b.md","lastUpdated":1789023840000}'),h={name:"llm/agent-sandbox-e2b.md"};function p(A,e,B,m,k,D){const t=c("Mermaid");return a(),s("div",null,[e[1]||(e[1]=r('<h1 id="e2b-docker-agent-沙箱" tabindex="-1">E2B / Docker agent 沙箱 <a class="header-anchor" href="#e2b-docker-agent-沙箱" aria-label="Permalink to &quot;E2B / Docker agent 沙箱&quot;">​</a></h1><div class="epigraph"><p>沙箱是已恢复的快照，不是冷启动的空虚机：控制面决定在哪跑、数据面用微型虚机真正跑；代理流量不经过决策 API。</p><footer>—— E2B 基础设施 ARCHITECTURE 与模板文档；对照 Agache 等 Firecracker，NSDI 2020</footer></div><p>编码代理一旦能写 bash，执行就必须离开开发者笔记本。E2B 把「给代理一台短暂的 Linux」做成产品：沙箱是隔离的虚机，从预启动快照恢复而不是从头引导，可暂停、再快照、再恢复；官方文档写同区域启动可到约 80–200 毫秒量级，会话上限按套餐到数小时至 24 小时。实现上，控制面 REST API 记账与调度，数据面编排器在节点上跑 <strong>Firecracker</strong> 微型虚机，虚机内的 <code>envd</code> 向 SDK 暴露进程与文件系统接口。模板来自 OCI/Docker 镜像：抽出文件系统、做供给、跑启动命令、再拍快照。本篇只写隔离边界与生命周期的高层架构。不写逃逸、提权、突破网络策略或任何利用步骤；默认场景是用户授权的不可信生成代码在隔离环境里运行。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/agent-harness-design">Harness</a> 若把命令发到宿主机，模型采样错误或提示注入造成的副作用会落到真实磁盘与凭证。容器（Docker 一类 OCI 运行时）用命名空间与 cgroup 隔离进程，但<strong>共享宿主机内核</strong>：系统调用仍进同一套内核。对「执行你刚写的任意代码」这一威胁模型，共享内核把内核漏洞的爆炸半径扩到整机与邻居租户。微型虚机给每个工作负载单独的客户内核，宿主机与客户之间隔着硬件虚拟化（KVM）。Firecracker 正是为无服务器多租户设计的轻量 VMM：设备模型刻意缩小，启动快、密度高。代理沙箱要回答的是：如何在「像一台完整 Linux」和「启动延迟可接受」之间，用快照而不是每次冷引导。</p><p>Docker 在这条线上仍有位置。它是模板的<strong>打包格式</strong>与本地开发默认运行时：镜像可复现依赖，CI 与单租户内部自动化常用容器就够。E2B 的模板流水线明确从容器文件系统走到可引导快照，说明二者不是互斥品牌，而是不同层：镜像描述「里面有什么」，微型虚机描述「与宿主机如何隔离」。把「用了 Docker」写成已经具备多租户不可信代码边界，是合同错误。</p><h3 id="快照恢复把启动从引导变成还原" tabindex="-1">快照恢复把启动从引导变成还原 <a class="header-anchor" href="#快照恢复把启动从引导变成还原" aria-label="Permalink to &quot;快照恢复把启动从引导变成还原&quot;">​</a></h3><p>E2B 架构文档的两条主轴：沙箱是恢复出来的快照（内存 + 磁盘 + 虚机状态进对象存储）；控制面与数据面分离，API 决定落点并在 Postgres/Redis 记账，编排器拥有 Firecracker、网络与存储，沙箱流量不经 API。内存页可按缺页惰性拉取，根文件系统用写时复制覆盖，因此只有碰到的数据才被取回。模板构建：基于定义起容器 → 抽文件系统 → 供给与分层命令 → 启动沙箱 → 可选 start/ready 命令 → 拍快照。内核在模板构建时固定（文档列举 LTS 6.1 系列按构建日期分档），要换内核只能重建模板。这是供给合同，不是运行时热升级。</p><p><span class="marginnote">公开数字是产品口径：同区域约 80 ms 级恢复、最长约 24 h 会话、超时后可暂停以保留状态。引用时写文档版本与套餐档。不要把某一周的内核小版本写进所有历史模板。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>生命周期：<code>create</code>（从模板快照恢复）→ SDK 经 <code>envd</code> 跑进程、读写文件、可选暴露端口 → <code>setTimeout</code> 续命 → <code>pause</code>/<code>snapshot</code> 或 <code>kill</code>。超时到期可以自动暂停而不是销毁，以便稍后从同一状态继续；暂停会重置连续运行窗口。信息查询返回沙箱 id、模板、起止时间。浏览器或 HTTP 客户端走边缘代理，按沙箱 id 路由到正确节点，仍不经过控制面业务 API。构建侧另有模板管理角色：把 Docker push 进来的镜像变成快照工件。</p><p>与本机 Docker 对照。本地 <code>docker run</code>：共享内核、镜像层缓存友好、调试简单，适合单用户、代码来源可信或已审计的任务。<a href="/llm/openhands">OpenHands</a> 一类平台默认把仓库挂进容器工作目录，隔离的是开发机污染，不是公有云多租户。E2B 一类服务把同一「给代理一台电脑」的 UX 换成微型虚机与按秒计费的生命周期。网络、文件系统挂载、出站代理是策略旋钮：默认应最小权限；把宿主机密钥直接挂进可写工作区，等于把隔离降回容器共享的信任假设。</p>',12)),(a(),i(E,null,{default:o(()=>[l(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SDK%5B%22SDK%20%2F%20CLI%22%5D%20--%3E%20API%5B%22%E6%8E%A7%E5%88%B6%E9%9D%A2%20API%EF%BC%9A%E8%B0%83%E5%BA%A6%E4%B8%8E%E9%85%8D%E9%A2%9D%22%5D%0A%20%20API%20--%3E%20ORCH%5B%22%E8%8A%82%E7%82%B9%E7%BC%96%E6%8E%92%E5%99%A8%22%5D%0A%20%20ORCH%20--%3E%20FC%5B%22Firecracker%20%E5%BE%AE%E5%9E%8B%E8%99%9A%E6%9C%BA%22%5D%0A%20%20FC%20--%3E%20ENVD%5B%22envd%EF%BC%9A%E8%BF%9B%E7%A8%8B%E4%B8%8E%E6%96%87%E4%BB%B6%20API%22%5D%0A%20%20ENVD%20--%3E%20PROC%5B%22%E4%BB%A3%E7%90%86%E7%94%9F%E6%88%90%E7%9A%84%E7%94%A8%E6%88%B7%E8%BF%9B%E7%A8%8B%22%5D%0A%20%20IMG%5B%22OCI%20%2F%20Docker%20%E6%A8%A1%E6%9D%BF%22%5D%20--%3E%20SNAP%5B%22%E9%A2%84%E5%90%AF%E5%8A%A8%E5%BF%AB%E7%85%A7%22%5D%0A%20%20SNAP%20--%3E%20FC%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h3 id="隔离边界要写进威胁模型-而不是写进演示脚本" tabindex="-1">隔离边界要写进威胁模型，而不是写进演示脚本 <a class="header-anchor" href="#隔离边界要写进威胁模型-而不是写进演示脚本" aria-label="Permalink to &quot;隔离边界要写进威胁模型，而不是写进演示脚本&quot;">​</a></h3><p>高层边界可以陈述，步骤不能给。容器：进程级隔离，内核共享，适合打包与可信 CI。微型虚机：客户内核 + 精简设备模型，适合多租户不可信代码。再往上还有用户态内核（gVisor）等折中，本篇不展开配置清单。产品若在虚机里再跑一层 Docker Engine，那是「虚机里的容器 UX」，隔离仍以虚机为准。评测应分开：功能（代码能否跑通）、密度与冷启动、以及失败时是否越出租户边界。后一项只能在授权的红队与供应商文档范围内讨论，博客只保留架构陈述。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>对模型，沙箱是又一种工具观察：命令的 stdout、文件内容、服务 URL。harness 决定何时 <code>create</code>、把哪段生成代码送进执行器、如何把超长输出卸盘。快照机制让「装好依赖的世界」成为可复制的先验，这与每次冷装包是不同的延迟结构。惰性内存与写时复制降低同时恢复大量沙箱时的存储放大，但第一次碰到的页面仍会付 I/O——把「80 ms」理解成「任意工作负载都已在内存里」，会低估缺页尾延迟。</p><p>控制面/数据面分离的机制意义：API 被打满或凭证泄漏，不应自动等于「能在别人的虚机里执行」。路由目录在 Redis，真实进程在节点上。反之，节点被攻破是另一类事故，要用租户隔离与密钥不进虚机来限爆。官方强调沙箱流量不经 API，是为了延迟，也是为了缩小控制面的数据面暴露。这些是架构意图，不是保证书。</p><p><span class="marginnote">Firecracker 论文（Agache 等，NSDI 2020）写的是轻量虚拟化与 Lambda 一类负载，不是 E2B 产品。引用时：隔离原语用论文与 AWS 开源项目；生命周期与模板用 E2B 文档。不要把 Lambda 的冷启动数字填进 E2B 表格。</span></p><h3 id="模板是信任根-镜像来源要当供应链" tabindex="-1">模板是信任根，镜像来源要当供应链 <a class="header-anchor" href="#模板是信任根-镜像来源要当供应链" aria-label="Permalink to &quot;模板是信任根，镜像来源要当供应链&quot;">​</a></h3><p>从 Docker 构建模板，等于把镜像里的软件当沙箱世界的初始条件。供应链风险（依赖投毒、过宽的基础镜像）与「代理写出恶意脚本」是两层：前者在构建时进入所有派生沙箱，后者在单次会话。构建应钉版本、扫已知漏洞、最小包集。运行时再安装的包只影响该会话或新快照。把构建与运行混成「代理自己 apt」且镜像长期复用，会把一次投毒写成全租户先验。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><h3 id="选容器还是微型虚机-先写谁不可信" tabindex="-1">选容器还是微型虚机，先写谁不可信 <a class="header-anchor" href="#选容器还是微型虚机-先写谁不可信" aria-label="Permalink to &quot;选容器还是微型虚机，先写谁不可信&quot;">​</a></h3><p>代码来源是本组织已审的自动化、单租户、可接受共享内核，Docker（加 seccomp、只读根、丢特权）常常够用，也更易在开发机复现。代码来源是模型即时生成、多租户同机、需要独立内核，微型虚机才是为该威胁模型设计的边界。E2B 把后者做成带 SDK 的云服务，并允许 BYOC/自托管；自托管仍要运维快照存储、编排与配额，并不是「不用想隔离」。网络隔离、出站白名单、禁止挂载生产密钥，无论哪一种运行时都要单独做——隔离原语不自动等于数据防泄漏。</p><p>不要把沙箱当成提示注入的完整补丁。注入可以让代理在<strong>已授权</strong>的沙箱里做坏事（删自己的工作区、对已允许的 URL 发请求）；沙箱限制的是爆炸半径是否到达宿主机与邻居。与 <a href="/llm/camel-injection-defense">CaMeL</a> 一类控制流/数据流政策是互补层。本仓库只讨论合法、用户授权的隔离执行；不提供任何突破隔离的办法。</p><p><span class="marginnote">出处：E2B 文档（沙箱生命周期、模板 how-it-works）与 e2b-dev/infra <em>ARCHITECTURE.md</em>；Firecracker：Agache 等，NSDI 2020。Docker 对照官方容器隔离模型（命名空间 / cgroup）。架构层描述，不含利用。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>代理沙箱要把不可信代码的副作用关在隔离计算里；E2B 用 Firecracker 快照恢复提供完整 Linux 与短启动。</li><li>Docker/OCI 是模板与本地打包层，共享内核，不能单独当作多租户不可信边界。</li><li>控制面调度、数据面跑虚机、<code>envd</code> 提供进程文件 API；流量不经决策 API。</li><li>威胁模型决定容器是否够用；沙箱不替代工具权限与注入防御。</li><li>出处：E2B 公开文档与架构说明；Firecracker NSDI 2020。</li></ul>',15))])}const g=n(h,[["render",p]]);export{b as __pageData,g as default};
